import { memo } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { Loader2 } from 'lucide-react'
import { ReasoningBlock } from '@/components/chat/ReasoningBlock'
import { ToolCallLine } from '@/components/chat/ToolCallLine'
import { CodeBlock } from '@/components/chat/CodeBlock'
import { MessageActions } from '@/components/chat/MessageActions'
import type { Message } from '@/lib/api'

interface MessageBubbleProps {
  message: Message
  isStreaming: boolean
  onRegenerate?: (messageId: number) => void
  onFeedback?: (messageId: number, rating: 'like' | 'dislike', comment?: string) => void
  onDeleteFeedback?: (messageId: number) => void
  onBookmark?: (messageId: number) => void
  onFeedbackOpen?: (messageId: number) => void
}

/** Markdown 代码块渲染器 */
const markdownComponents = {
  code({ node: _node, className, children, ...props }: any) {
    const match = /language-(\w+)/.exec(className || '')
    const isInline = !match
    if (isInline) {
      return <code className="rounded bg-muted px-1.5 py-0.5 text-xs font-mono" {...props}>{children}</code>
    }
    return <CodeBlock code={String(children).replace(/\n$/, '')} language={match?.[1] || 'text'} />
  },
}

/**
 * 消息气泡组件
 * - 根据 role 分发到 UserMessage / AssistantMessage
 * - 使用 React.memo 避免不必要的重渲染
 */
export const MessageBubble = memo(function MessageBubble({
  message,
  isStreaming,
  onRegenerate,
  onFeedback,
  onDeleteFeedback,
  onBookmark,
  onFeedbackOpen,
}: MessageBubbleProps) {
  const msg = message

  return (
    <div className="group">
      {msg.role === 'user' ? (
        /* 用户消息：气泡样式，右对齐 */
        <div className="flex justify-end">
          <div className="max-w-[80%] rounded-2xl bg-primary px-4 py-2.5 text-sm text-primary-foreground">
            <p className="whitespace-pre-wrap">{msg.content}</p>
          </div>
        </div>
      ) : (
        /* 模型回复：无气泡，全宽 */
        <div className="space-y-2 text-sm">
          <AssistantMessage msg={msg} isStreaming={isStreaming} />
        </div>
      )}
      {/* 消息操作栏（流式中不显示） */}
      {msg.content && !isStreaming && (
        <div className="mt-1">
          <MessageActions
            content={msg.content}
            role={msg.role as 'user' | 'assistant'}
            timestamp={msg.created_at}
            messageId={msg.id}
            feedback={msg.feedback}
            isBookmarked={msg.bookmarked}
            elapsedMs={msg.elapsed_ms}
            onRegenerate={msg.role === 'assistant' && onRegenerate ? () => onRegenerate(msg.id) : undefined}
            onFeedback={onFeedback ? (rating, comment) => onFeedback(msg.id, rating, comment) : undefined}
            onDeleteFeedback={onDeleteFeedback ? () => onDeleteFeedback(msg.id) : undefined}
            onBookmark={onBookmark ? () => onBookmark(msg.id) : undefined}
            onFeedbackOpen={onFeedbackOpen ? () => onFeedbackOpen(msg.id) : undefined}
          />
        </div>
      )}
    </div>
  )
})

/** Assistant 消息内容（思考 + 工具调用 + 正文） */
function AssistantMessage({ msg, isStreaming }: { msg: Message; isStreaming: boolean }) {
  return (
    <div className="space-y-2">
      {/* 思考过程 */}
      {msg.thinking && (
        <ReasoningBlock
          text={msg.thinking}
          isStreaming={isStreaming && !msg.content}
        />
      )}
      {/* 工具调用 */}
      {msg.tool_calls && msg.tool_calls.length > 0 && (
        <div className="space-y-1.5">
          {msg.tool_calls.map((tc) => (
            <ToolCallLine key={tc.id} toolCall={tc} />
          ))}
        </div>
      )}
      {/* 正文内容 */}
      {msg.content ? (
        <div className="prose prose-sm dark:prose-invert max-w-none">
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            components={markdownComponents}
          >
            {msg.content}
          </ReactMarkdown>
        </div>
      ) : !msg.thinking && (!msg.tool_calls || msg.tool_calls.length === 0) ? (
        <div className="flex items-center gap-2 text-muted-foreground">
          <Loader2 className="h-3.5 w-3.5 animate-spin" />
          <span className="text-xs">思考中...</span>
        </div>
      ) : null}
    </div>
  )
}
